import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Checkbox, Flex, Input } from 'antd';

import { EFilters, useFilters } from 'features/Filters';

interface IChannelsFiltersProps extends HTMLAttributes<HTMLDivElement> {}

export const ChannelsFilters: FC<IChannelsFiltersProps> = ({ ...props }) => {
	const { t } = useTranslation();

	const { getFilterValue, onFilterChange } = useFilters(true);

	return (
		<Flex {...props} vertical gap={8}>
			<Input.Search
				placeholder={t('Поиск')}
				onSearch={(value) => onFilterChange(EFilters.SOURCE, value)}
				value={getFilterValue(EFilters.SOURCE) || ''}
				allowClear
				size="large"
			/>

			<Checkbox
				onChange={(e) => {
					onFilterChange(EFilters.MMP_LINK, e.target.checked ? 'true' : null);
				}}
				checked={getFilterValue(EFilters.MMP_LINK) === 'true'}>
				{t('Неактивные')}
			</Checkbox>
		</Flex>
	);
};
