import { EBaseApiTags } from 'shared/typings';

import { enhancedApi } from './codegen.api';

export const sourceApi = enhancedApi.enhanceEndpoints({
	addTagTypes: [EBaseApiTags.CHANNELS],
	endpoints: {
		sourcesList: {
			providesTags: [EBaseApiTags.CHANNELS],
		},
		sourcesRetrieve: {
			providesTags: [EBaseApiTags.CHANNELS],
		},
		sourcesUpdate: {
			invalidatesTags: (_, error) => (error ? [] : [EBaseApiTags.CHANNELS]),
		},
		sourcesPartialUpdate: {
			invalidatesTags: (_, error) => (error ? [] : [EBaseApiTags.CHANNELS]),
		},
	},
});

export const {
	useSourcesListQuery,
	useSourcesRetrieveQuery,
	useSourcesUpdateMutation,
	useSourcesPartialUpdateMutation,
} = sourceApi;
